def dif_Square(n: int) -> bool:
    # A number n can be represented as a difference of two squares (a² - b²)
    # if and only if n is NOT congruent to 2 modulo 4.
    # This holds for all integers a,b (positive, negative or zero).
    return n % 4 != 2


