def get_total_number_of_sequences(n: int, m: int) -> int:
    if n == 0:
        return 0
    # dp[i][x]: number of sequences of length i ending with x
    dp = [ [0]*(m+1) for _ in range(n+1) ]
    # Base case: sequences of length 1
    for x in range(1, m+1):
        dp[1][x] = 1

    for i in range(2, n+1):
        # To optimize, we can keep a prefix sum of dp[i-1]
        # but since we must sum dp[i-1][prev] over prev <= x/2 (since x >= 2*prev => prev <= x/2)
        prefix = [0]*(m+1)
        for x in range(1, m+1):
            prefix[x] = prefix[x-1] + dp[i-1][x]

        for x in range(1, m+1):
            max_prev = x//2
            if max_prev >= 1:
                dp[i][x] = prefix[max_prev]
            else:
                dp[i][x] = 0

    return sum(dp[n][1:])


