def find_Max(nums):
    if not nums:
        return None
    left, right = 0, len(nums) - 1
    if nums[left] < nums[right]:
        return nums[right]
    while left < right:
        mid = (left + right) // 2
        if nums[mid] > nums[right]:
            left = mid + 1
        else:
            right = mid
    # left is now the index of the smallest element
    # max is element before smallest, taking care of wrap-around
    return nums[left - 1]


