def compute_Last_Digit(a, b):
    if a > b:
        return None
    # (b! / a!) = (a+1)*(a+2)*...*b
    if a == b:
        return 1  # factorial division is 1

    product = 1
    for x in range(a + 1, b + 1):
        product = (product * (x % 10)) % 10
        if product == 0:
            return 0  # once last digit is zero, it remains zero

    return product


