def dif_Square(n: int) -> bool:
    # A number n can be represented as a difference of squares a² - b² if and only if:
    # n = (a-b)(a+b)
    # Let x = a-b, y = a+b, then n = x*y
    # For integers a,b, x and y must be integers with the same parity (both odd or both even),
    # and y > x > 0 (or vice versa for negative n).
    #
    # Equivalently, n can be expressed as difference of squares if and only if n is not congruent to 2 mod 4.
    # (i.e., n % 4 != 2)
    #
    # Proof:
    # - If n is odd, it can always be represented (since odd = difference of consecutive squares).
    # - If n is divisible by 4, it can be represented.
    # - If n % 4 == 2, it cannot be represented.

    return n % 4 != 2


