def next_smallest_palindrome(n: int) -> int:
    # Helper to check if a number is palindrome
    def is_palindrome(x: int) -> bool:
        s = str(x)
        return s == s[::-1]

    # If n <= 0, no smaller palindrome positive number exists
    if n <= 0:
        return -1  # or possibly 0? but no positive palindrome less than 0

    # Special case: if n <= 10, the largest palindrome less than n is n-1 (single-digit palindromes)
    if n <= 10:
        return n - 1

    # For n > 10, try to construct palindrome less than n without checking all numbers one by one
    s = str(n)
    length = len(s)

    # Decrement n by 1 to ensure strictly smaller palindrome
    n -= 1
    s = str(n)

    while True:
        if is_palindrome(n):
            return n
        n -= 1


