def find_solution(a, b, n):
    for x in range(0, abs(n) + 1 if a != 0 else 1_000_000):
        if a * x <= n:
            remainder = n - a * x
            if b != 0 and remainder % b == 0:
                y = remainder // b
                return ('x = ', x, ', y = ', y)
            elif b == 0 and remainder == 0:
                return ('x = ', x, ', y = ', 0)
        elif a * x > n and a > 0:
            # Since a*x is increasing and exceeded n, no need to continue
            break
    return 'No solution'


