def get_total_number_of_sequences(n: int, m: int) -> int:
    from functools import lru_cache

    @lru_cache(None)
    def count_sequences(length: int, prev: int) -> int:
        if length == n:
            return 1
        total = 0
        start = max(1, 2 * prev)
        for next_elem in range(start, m + 1):
            total += count_sequences(length + 1, next_elem)
        return total

    total_count = 0
    for first_elem in range(1, m + 1):
        total_count += count_sequences(1, first_elem)
    return total_count


