import re

def text_match_two_three(s: str) -> bool:
    # The pattern matches 'a' followed immediately by 2 or 3 'b's, but not more than 3.
    # The previous pattern would match 'abbb...' too, which is correct.
    # However, the issue is if the string contains 'abbbb' (4 b's), it should return False.
    # So we need to ensure that exactly 2 or 3 'b's follow the 'a', and not more.
    # We can do this by ensuring that after the 2-3 b's, the next character is not 'b' (or end of string).

    return bool(re.search(r'ab{2,3}(?!b)', s))


