def smallest_missing(arr, left, right):
    if left > right:
        # When no elements in the current segment, the smallest missing is left (the expected value)
        return left
    mid = (left + right) // 2
    # Expected value at mid index if no missing number is arr[left] + (mid - left)
    expected = arr[left] + (mid - left)
    if arr[mid] == expected:
        # No missing number from left to mid, search right half
        return smallest_missing(arr, mid + 1, right)
    else:
        # Missing number in left half
        return smallest_missing(arr, left, mid)


