def find_Max(nums):
    if not nums:
        return None  # or raise an error if empty input is not allowed

    left, right = 0, len(nums) - 1
    # If the array is not rotated (last element > first element), the max is the last element
    if nums[left] < nums[right]:
        return nums[right]

    # Binary search for the max element (pivot point)
    while left < right:
        mid = (left + right) // 2
        # If mid element is greater than the rightmost element,
        # the max is in the right half including mid
        if nums[mid] > nums[right]:
            left = mid + 1
        else:
            right = mid

    # After the loop, left points to the smallest element,
    # so max is the element before left, or last if left == 0
    return nums[left - 1] if left > 0 else nums[-1]


