def substract_elements(a, b):
    if isinstance(a, (list, tuple)) and isinstance(b, (list, tuple)):
        if type(a) is tuple and type(b) is tuple:
            return tuple(substract_elements(x, y) for x, y in zip(a, b))
        elif type(a) is list and type(b) is list:
            return [substract_elements(x, y) for x, y in zip(a, b)]
        else:
            # If types differ (one list, one tuple), return list by default
            return [substract_elements(x, y) for x, y in zip(a, b)]
    else:
        return a - b


