def get_noOfways(n, m):
    if m != 2:
        return 0
    if n <= 0:
        return 0
    # Number of ways to tile 2 x n board with 2 x 1 tiles is Fibonacci-like:
    # ways(1) = 1, ways(2) = 2, ways(n) = ways(n-1) + ways(n-2)
    a, b = 1, 2
    if n == 1:
        return a
    if n == 2:
        return b
    for _ in range(3, n + 1):
        a, b = b, a + b
    return b


