from math import gcd
from functools import reduce

def get_gcd(arr):
    # Filter out zeros and take absolute values
    non_zero = [abs(x) for x in arr if x != 0]
    if not non_zero:
        # If all elements are zero, gcd is defined as 0 (or could raise error),
        # but since gcd must be strictly positive, return 0 is not valid.
        # The most standard behavior here is to return 0 or raise an error.
        # We'll return 0 to indicate no positive gcd.
        return 0
    return reduce(gcd, non_zero)


