def next_smallest_palindrome(n: int) -> int:
    s = str(n)
    length = len(s)

    # Helper: Check if all digits are '9'
    if all(ch == '9' for ch in s):
        # Next palindrome is 10..01 (length+1 digits)
        return int('1' + ('0' * (length - 1)) + '1')

    # Split into left, middle, right
    half = length // 2
    odd = (length % 2 != 0)

    if odd:
        left = s[:half]
        middle = s[half]
        right = s[half+1:]
    else:
        left = s[:half]
        middle = ''
        right = s[half:]

    # Construct palindrome by mirroring left + middle (if odd)
    if odd:
        pal = left + middle + left[::-1]
    else:
        pal = left + left[::-1]

    # If palindrome > n, return it
    if int(pal) > n:
        return int(pal)

    # Otherwise, increment middle part and mirror again
    if odd:
        # Increment middle digit and handle carry if needed
        left_middle_num = left + middle
        incremented = str(int(left_middle_num) + 1)
        # If length changed due to carry increment, adjust
        if len(incremented) > len(left_middle_num):
            # e.g. 999 + 1 = 1000, so palindrome length increases by 1
            left = incremented[:-1]
            middle = incremented[-1]
        else:
            left = incremented[:-1]
            middle = incremented[-1]
        pal = left + middle + left[::-1]
    else:
        # Even length: increment left half and mirror
        incremented = str(int(left) + 1)
        # If length changed due to carry increment, adjust
        if len(incremented) > len(left):
            # e.g. 99 + 1 = 100, palindrome length increases by 1
            # For even length, palindrome length increases by 1, e.g. 9999 -> 10001
            pal = incremented + incremented[:-1][::-1]
            return int(pal)
        else:
            pal = incremented + incremented[::-1]

    return int(pal)


