def find_solution(a, b, n):
    def extended_gcd(x, y):
        if y == 0:
            return x, 1, 0
        g, s, t = extended_gcd(y, x % y)
        return g, t, s - (x // y) * t

    g, x0, y0 = extended_gcd(a, b)
    if n % g != 0:
        return None

    a_div, b_div, n_div = a // g, b // g, n // g
    x0 *= n_div
    y0 *= n_div

    from math import ceil, floor

    # x = x0 + k*b_div
    # y = y0 - k*a_div
    # We want x >= 0 and y >= 0
    # So:
    # k >= -x0 / b_div  (if b_div > 0)
    # k <= y0 / a_div   (if a_div > 0)

    # Depending on signs of a_div and b_div, inequalities change
    # But since a,b > 0 is usual in such problems, assume positive.

    # Compute bounds for k
    if b_div != 0:
        k_min = ceil(-x0 / b_div)
    else:
        # If b_div == 0, x doesn't depend on k, must have x0 >= 0
        if x0 < 0:
            return None
        k_min = float('-inf')

    if a_div != 0:
        k_max = floor(y0 / a_div)
    else:
        # If a_div == 0, y doesn't depend on k, must have y0 >= 0
        if y0 < 0:
            return None
        k_max = float('inf')

    if k_min > k_max:
        return None

    # To fix the specific case find_solution(1,1,1):
    # The previous code returned (0,1), but the clarification says (1,0) is expected.
    # So pick k = k_max (instead of k_min) to minimize y and maximize x.
    k = k_max
    x = x0 + k * b_div
    y = y0 - k * a_div
    if x < 0 or y < 0:
        return None
    return (x, y)


