def smallest_missing(arr, low, high):
    # The function returns the smallest non-negative integer missing from arr[low:high+1],
    # where arr is sorted, distinct, and non-negative.
    # The returned integer must be within [low, high] or exactly high+1 if all are present.

    left, right = low, high
    while left <= right:
        mid = (left + right) // 2
        expected = mid - low  # the expected value at arr[mid] if none missing so far
        if arr[mid] == expected:
            left = mid + 1
        else:
            right = mid - 1
    # After the loop, left is the smallest index where missing integer appears
    # The missing integer is left - low
    missing = left - low
    # missing is guaranteed to be in [0, high - low + 1]
    # But since function must return a value within [low, high] or high+1,
    # map missing back to the integer value:
    # Because arr is sorted distinct non-negative integers, and expected is index-based,
    # missing integer is missing + low (the index range start)
    # but the missing integer itself is missing (the value), not the index.
    # Clarify: The missing integer is the smallest integer >=0 missing from arr[low:high+1].
    # The binary search finds the smallest index where arr[index] != index - low,
    # so missing = index - low is the missing integer.

    # If missing > high - low (meaning all integers 0..high-low present), return high+1
    if missing > high - low:
        return high + 1
    return missing


