def permute_string(s):
    result = []
    chars = list(s)

    def backtrack(start):
        if start == len(chars):
            result.append("".join(chars))
            return
        for i in range(start, len(chars)):
            chars[start], chars[i] = chars[i], chars[start]
            backtrack(start + 1)
            chars[start], chars[i] = chars[i], chars[start]

    backtrack(0)
    return result


