def find_Max(nums):
    if not nums:
        return None  # or raise an exception if preferred

    left, right = 0, len(nums) - 1

    # If array is not rotated (sorted ascending), the max is the last element
    if nums[left] < nums[right]:
        return nums[right]

    while left < right:
        mid = (left + right) // 2
        # If mid element is greater than the right element,
        # max must be in the right half including mid
        if nums[mid] > nums[right]:
            left = mid
        else:
            # max is in the left half excluding mid
            right = mid - 1

    return nums[left]


