def lucky_num(n):
    numbers = list(range(1, 2 * n * n, 2))  # start with odd numbers large enough
    idx = 1
    while idx < len(numbers) and len(numbers) > n:
        step = numbers[idx]
        if step > len(numbers):
            break
        # Remove every step-th number from the list (1-based indexing)
        numbers = [num for i, num in enumerate(numbers, start=1) if i % step != 0]
        idx += 1
    return numbers[:n]


