def compute_Last_Digit(a: int, b: int) -> int:
    # The product is (a+1)*(a+2)*...*b
    # If b > a, and the product includes a multiple of 10, the last digit is 0.
    # So first check if there's any multiple of 10 in (a+1,...,b)
    # If yes, last digit is 0.
    # Else, multiply modulo 10 all numbers from a+1 to b and return result.

    if b <= a:
        # If b == a, product is empty (factorial(b)/factorial(a) = 1)
        return 1

    # Check if there is any multiple of 10 in range (a+1 to b)
    # A number is multiple of 10 if divisible by 10
    # If any number in that range is divisible by 10, last digit is 0
    start = a + 1
    end = b

    # If range includes any multiple of 10 -> last digit is 0
    if (start + 9) // 10 * 10 <= end:
        return 0

    # Otherwise, compute product modulo 10
    last_digit = 1
    for x in range(start, end + 1):
        last_digit = (last_digit * (x % 10)) % 10

    return last_digit


