def dif_Square(n: int) -> bool:
    # A number n can be represented as a difference of squares a² - b² = n
    # Using identity a² - b² = (a-b)(a+b) = n
    # Let x = a-b, y = a+b, so n = x*y
    # Since a and b are integers, (x+y) and (y-x) must both be even (because a = (x+y)/2, b = (y-x)/2)
    # So x and y must have the same parity (both even or both odd)
    # Therefore, n can be represented as difference of squares if and only if n has a factorization n = x*y
    # where x and y have the same parity.

    # Handle zero case:
    if n == 0:
        return True  # 0 = 0² - 0²

    # Consider all factor pairs (x,y) of n: x*y = n
    # We only need to check absolute values because if (x,y) is a factor pair then so is (-x,-y)
    # and parity is preserved under negation.

    abs_n = abs(n)
    from math import isqrt

    for x in range(1, isqrt(abs_n) + 1):
        if abs_n % x == 0:
            y = abs_n // x
            # Check parity of x and y:
            if (x % 2) == (y % 2):
                # Now consider sign assignments to match n:
                # Since n can be negative, we can choose signs of x,y to get n:
                # (x*y = n) or (-x)*(-y) = n, but since abs(x*y) = abs(n)
                # We must check if n and x*y have same sign or if we can assign signs to x,y to get n.
                # Actually, for any factor pair (x,y), we can assign signs to x,y to get n because:
                # if n > 0, (x,y) or (-x,-y)
                # if n < 0, (x,-y) or (-x,y)
                # So sign can be adjusted freely.
                return True
    return False


