def next_smallest_palindrome(num: int) -> int:
    s = str(num)
    length = len(s)

    # Helper to check palindrome
    def is_palindrome(x: str) -> bool:
        return x == x[::-1]

    # For num < 9, the next palindrome is num+1 (since single digit palindromes)
    if num < 9:
        return num + 1

    # We'll generate the next palindrome strictly greater than num

    # Split into left, middle and right depending on length even/odd
    half_len = length // 2
    odd_len = (length % 2 != 0)

    left = s[:half_len]
    middle = s[half_len] if odd_len else ''
    right = s[half_len + (1 if odd_len else 0):]

    # Form palindrome by mirroring left + middle
    if odd_len:
        palindrome = left + middle + left[::-1]
    else:
        palindrome = left + left[::-1]

    if int(palindrome) > num:
        return int(palindrome)

    # Need to increment the middle part and mirror again
    if odd_len:
        # increment the middle digit + left as a whole number
        # e.g. left='123', middle='4' -> number = 1234
        increment_part = left + middle
        increment_number = int(increment_part) + 1
        increment_str = str(increment_number)

        if len(increment_str) > len(increment_part):
            # overflow, e.g. 999 + 1 = 1000
            # new palindrome length increases by 1
            # e.g. 99999 -> next palindrome is 100001
            return int('1' + ('0' * (length - 1)) + '1')

        new_left = increment_str[:-1]
        new_middle = increment_str[-1]
        palindrome = new_left + new_middle + new_left[::-1]
        return int(palindrome)
    else:
        # even length
        # increment left part, mirror again
        increment_number = int(left) + 1
        increment_str = str(increment_number)

        if len(increment_str) > len(left):
            # e.g. 99 + 1 = 100, length increased
            # next palindrome length increases by 1 and is of form 100001 for 6 digits
            return int('1' + ('0' * (length - 1)) + '1')

        palindrome = increment_str + increment_str[::-1]
        return int(palindrome)


