def find_solution(a, b, n):
    def extended_gcd(aa, bb):
        if bb == 0:
            return (aa, 1, 0)
        else:
            g, x1, y1 = extended_gcd(bb, aa % bb)
            x = y1
            y = x1 - (aa // bb) * y1
            return (g, x, y)

    g, x0, y0 = extended_gcd(a, b)
    if n % g != 0:
        return "No solution"

    # Scale the solution by n//g
    x0 *= n // g
    y0 *= n // g

    # a/g and b/g
    a_g = a // g
    b_g = b // g

    # We want the smallest non-negative x among all solutions:
    # General solution: x = x0 + k*(b/g), y = y0 - k*(a/g)
    # Find k such that x >= 0 and x is minimal non-negative:
    # Solve x0 + k*b_g >= 0 -> k >= -x0 / b_g
    # If b_g > 0:
    #   k_min = ceil(-x0 / b_g)
    # else if b_g < 0:
    #   k_min = floor(-x0 / b_g)
    # We pick k = k_min to get smallest non-negative x.

    if b_g == 0:
        # Then x = x0 fixed. Just check if x0 >= 0:
        if x0 >= 0:
            return (x0, y0)
        else:
            return "No solution"

    import math

    if b_g > 0:
        k = math.ceil(-x0 / b_g)
    else:
        k = math.floor(-x0 / b_g)

    x = x0 + k * b_g
    y = y0 - k * a_g

    if x < 0:
        return "No solution"
    return (x, y)


