def filter_data(data, min_height=None, max_height=None, min_width=None, max_width=None):
    """
    Filters a dictionary of students by height and width criteria.

    Parameters:
    - data: dict mapping student names to dicts with 'height' and 'width' keys.
    - min_height: minimum height inclusive (or None to ignore).
    - max_height: maximum height inclusive (or None to ignore).
    - min_width: minimum width inclusive (or None to ignore).
    - max_width: maximum width inclusive (or None to ignore).

    Returns:
    - dict of students meeting all specified criteria.
    """
    filtered = {}
    for name, dims in data.items():
        h = dims.get('height')
        w = dims.get('width')
        if h is None or w is None:
            continue
        if min_height is not None and h < min_height:
            continue
        if max_height is not None and h > max_height:
            continue
        if min_width is not None and w < min_width:
            continue
        if max_width is not None and w > max_width:
            continue
        filtered[name] = dims
    return filtered


