def lucky_num(n):
    if n <= 0:
        return []

    # Start with a list of odd numbers (the sieve always starts with odd numbers)
    nums = list(range(1, 1000000, 2))  # large enough to get first n lucky numbers

    idx = 1  # index in nums for the sieve step (1-based in description, 0-based here)
    while len(nums) < n or idx < len(nums):
        if idx >= len(nums):
            break
        step = nums[idx]
        if step > len(nums):
            break
        # Remove every step-th number from the list (1-based counting)
        # Note: The current list is zero-indexed, so remove elements at positions step-1, 2*step-1, ...
        nums = [num for i, num in enumerate(nums) if (i + 1) % step != 0]
        idx += 1

        if len(nums) >= n and idx >= n:
            # Optimization: once we have enough lucky numbers and have done enough sieve steps, stop
            break

    return nums[:n]


