def dif_Square(n: int) -> bool:
    # A number n can be expressed as a difference of squares:
    # n = a^2 - b^2 = (a-b)(a+b)
    # For integers a > b >= 0, (a-b) and (a+b) are positive integers.
    #
    # So n = x * y where x = a-b, y = a+b and y > x > 0
    # Also, a = (x+y)/2 and b = (y - x)/2 must be integers, so (x+y) and (y-x) must be even.
    #
    # This is equivalent to saying that n can be factored into two positive integers of the same parity.
    #
    # Special case: n = 0 can be represented as 0^2 - 0^2 = 0, so return True

    if n == 0:
        return True

    abs_n = abs(n)
    for x in range(1, int(abs_n**0.5) + 1):
        if abs_n % x == 0:
            y = abs_n // x
            # Check if x and y have the same parity
            if (x + y) % 2 == 0 and (y - x) % 2 == 0 and y > x > 0:
                # For negative n, difference of squares can still be represented by swapping a and b,
                # but since a > b >= 0, and difference is a^2 - b^2,
                # negative n can be represented if n = -(a^2 - b^2) = b^2 - a^2,
                # so check if -n can be represented instead.
                if n > 0:
                    return True
                else:
                    # For negative n, difference of squares with a > b >= 0 is not possible.
                    # Because a^2 - b^2 >= 0 for a >= b >= 0.
                    # So negative n cannot be represented.
                    return False
    return False


