import math

def volume_sphere(*args, **kwargs):
    """
    Calculate the volume of a 3D object.

    If called with a single positional float or int argument, it is treated as the radius of a sphere.
    If called with keyword argument 'shape', it accepts:
      - shape='sphere', requires 'radius'
      - shape='cylinder', requires 'radius' and 'height'
      - shape='cone', requires 'radius' and 'height'
      - shape='cube', requires 'side'
      - shape='rectangular_prism', requires 'length', 'width', and 'height'
      - shape='ellipsoid', requires 'a', 'b', and 'c' (semi-axes)

    Returns the volume as a float.
    Raises ValueError if required parameters are missing or invalid.
    """
    if args and not kwargs:
        # Assume single argument is radius for a sphere
        if len(args) != 1:
            raise ValueError("Expected a single positional argument for radius.")
        radius = args[0]
        if not (isinstance(radius, (int, float)) and radius >= 0):
            raise ValueError("Radius must be a non-negative number.")
        return (4/3) * math.pi * radius**3

    shape = kwargs.get('shape', 'sphere').lower()

    if shape == 'sphere':
        radius = kwargs.get('radius')
        if radius is None or not isinstance(radius, (int, float)) or radius < 0:
            raise ValueError("Sphere requires a non-negative 'radius' parameter.")
        return (4/3) * math.pi * radius**3

    elif shape == 'cylinder':
        radius = kwargs.get('radius')
        height = kwargs.get('height')
        if radius is None or height is None:
            raise ValueError("Cylinder requires 'radius' and 'height'.")
        if not all(isinstance(x, (int, float)) and x >= 0 for x in [radius, height]):
            raise ValueError("'radius' and 'height' must be non-negative numbers.")
        return math.pi * radius**2 * height

    elif shape == 'cone':
        radius = kwargs.get('radius')
        height = kwargs.get('height')
        if radius is None or height is None:
            raise ValueError("Cone requires 'radius' and 'height'.")
        if not all(isinstance(x, (int, float)) and x >= 0 for x in [radius, height]):
            raise ValueError("'radius' and 'height' must be non-negative numbers.")
        return (1/3) * math.pi * radius**2 * height

    elif shape == 'cube':
        side = kwargs.get('side')
        if side is None or not isinstance(side, (int, float)) or side < 0:
            raise ValueError("Cube requires a non-negative 'side' parameter.")
        return side**3

    elif shape == 'rectangular_prism':
        length = kwargs.get('length')
        width = kwargs.get('width')
        height = kwargs.get('height')
        if None in (length, width, height):
            raise ValueError("Rectangular prism requires 'length', 'width', and 'height'.")
        if not all(isinstance(x, (int, float)) and x >= 0 for x in [length, width, height]):
            raise ValueError("'length', 'width', and 'height' must be non-negative numbers.")
        return length * width * height

    elif shape == 'ellipsoid':
        a = kwargs.get('a')
        b = kwargs.get('b')
        c = kwargs.get('c')
        if None in (a, b, c):
            raise ValueError("Ellipsoid requires 'a', 'b', and 'c' (semi-axes).")
        if not all(isinstance(x, (int, float)) and x >= 0 for x in [a, b, c]):
            raise ValueError("'a', 'b', and 'c' must be non-negative numbers.")
        return (4/3) * math.pi * a * b * c

    else:
        raise ValueError(f"Unsupported shape '{shape}'. Supported shapes: sphere, cylinder, cone, cube, rectangular_prism, ellipsoid.")

