def next_smallest_palindrome(num: int) -> int:
    s = str(num + 1)
    length = len(s)

    # Helper to check if a string is palindrome
    def is_palindrome(st):
        return st == st[::-1]

    while True:
        if is_palindrome(s):
            return int(s)
        # Construct the next palindrome based on the left half and mirror it
        half = (len(s) + 1) // 2
        left = s[:half]
        if len(s) % 2 == 0:
            pal_candidate = left + left[::-1]
        else:
            pal_candidate = left + left[-2::-1]

        if pal_candidate > s:
            return int(pal_candidate)
        # Increment the left half and rebuild palindrome
        left_num = int(left) + 1
        left = str(left_num)
        if len(left) > half:  # e.g. 999 + 1 = 1000 increases length
            s = '1' + ('0' * (length - 1)) + '1'
            length += 1
            s = str(int(s))  # ensure no leading zeros or such
        else:
            if len(s) % 2 == 0:
                s = left + left[::-1]
            else:
                s = left + left[-2::-1]


