def find_solution(a, b, n):
    def extended_gcd(aa, bb):
        if bb == 0:
            return (aa, 1, 0)
        gcd, x1, y1 = extended_gcd(bb, aa % bb)
        x = y1
        y = x1 - (aa // bb) * y1
        return gcd, x, y

    gcd, x0, y0 = extended_gcd(a, b)
    if n % gcd != 0:
        return "No solution"
    mul = n // gcd
    x = x0 * mul
    y = y0 * mul
    return ('x = ', x, ', y = ', y)


