from functools import lru_cache

def get_total_number_of_sequences(n: int, m: int) -> int:
    @lru_cache(None)
    def count(pos: int, prev: int) -> int:
        if pos == n:
            return 1
        total = 0
        start = max(1, 2 * prev) if prev != 0 else 1
        for val in range(start, m + 1):
            total += count(pos + 1, val)
