import re

def text_match_two_three(text):
    pattern = r"ab{2,3}"
    match = re.search(pattern, text)
    if match:
        # re.search() returns the first match, but ensure it returns the longest match of 2 or 3 'b's after 'a'
        # Because regex is greedy by default, the match.group(0) should already be the longest possible match.
        # However, if the match is shorter than 3 'b's and longer possible match exists, we need to verify.

        # To ensure the longest match (2 or 3 'b's), we can try to match all occurrences and pick the longest
        matches = re.findall(pattern, text)
        if matches:
            # return the longest match
            return max(matches, key=len)
        else:
            return "Not matched!"
    else:
        return "Not matched!"


