def remove_column(data, index):
    if isinstance(data, list):
        # If the list contains sublists, remove the element at index from each sublist
        result = []
        for item in data:
            if isinstance(item, list):
                # Remove element at index if possible
                if 0 <= index < len(item):
                    result.append(item[:index] + item[index+1:])
                else:
                    # If index out of range, keep sublist as is
                    result.append(item[:])
            else:
                # If item is not a list, keep as is
                result.append(item)
        return result
    elif isinstance(data, dict):
        # Recursively process dict values
        return {k: remove_column(v, index) for k, v in data.items()}
    else:
        # For any other type, return as is
        return data


