def repeat_tuples(data, times):
    """
    Repeat each tuple in the input iterable 'data' 'times' times, 
    concatenating the repetitions side-by-side to form longer tuples.

    Parameters:
    - data: iterable of tuples
    - times: int, number of times to repeat each tuple

    Returns:
    - list of tuples, each tuple repeated 'times' times in sequence
    """
    if times < 0:
        raise ValueError("times must be non-negative")
    return [tuple(element for _ in range(times) for element in tup) for tup in data]


