def lucky_num(n):
    numbers = list(range(1, 2 * n * 10))  # overshoot to ensure we get enough lucky numbers
    idx = 1  # start removing every 2nd number
    while idx < len(numbers) and len(numbers) < n:
        step = numbers[idx]
        if step > len(numbers):
            break
        # Remove every step-th number from the list (1-based index)
        del numbers[step - 1::step]
        idx += 1
    return numbers[:n]


