def dif_Square(n: int) -> bool:
    # A number n can be expressed as a difference of squares (a² - b² = n)
    # if and only if n can be factored into two integers x and y such that:
    # n = x * y, and x and y have the same parity (both odd or both even).
    #
    # This comes from the identity:
    # a² - b² = (a - b)(a + b) = n
    #
    # So if n = x * y with x = a-b and y = a+b,
    # then a = (x + y) / 2 and b = (y - x) / 2 must be integers.
    #
    # Therefore, x and y must be both even or both odd.
    #
    # Check all factor pairs of |n| to find such a pair.

    if n == 0:
        # 0 = 0² - 0² trivially
        return True

    abs_n = abs(n)
    from math import isqrt

    for x in range(1, isqrt(abs_n) + 1):
        if abs_n % x == 0:
            y = abs_n // x
            # Check parity of x and y
            if (x % 2) == (y % 2):
                # parity matches, so n can be expressed as difference of squares
                return True
    return False


