def find_solution(a, b, n):
    # Extended Euclidean Algorithm to find gcd and one solution (x0,y0) for a*x + b*y = gcd(a,b)
    def extended_gcd(aa, bb):
        if bb == 0:
            return (aa, 1, 0)
        gcd, x1, y1 = extended_gcd(bb, aa % bb)
        x = y1
        y = x1 - (aa // bb) * y1
        return gcd, x, y

    gcd, x0, y0 = extended_gcd(a, b)
    if n % gcd != 0:
        return None  # no solution

    # scale the solution to n
    x0 *= n // gcd
    y0 *= n // gcd

    # a and b divided by gcd
    a_div = a // gcd
    b_div = b // gcd

    # We want to find t so that x = x0 + t * (b/gcd) >= 0
    # x >= 0 => t >= (-x0) / (b/gcd)

    # Since b_div might be zero (if b=0), handle that case:
    if b_div == 0:
        # Then equation is a*x = n
        # We already have x0, y0 from above which is a solution
        # If x0 >= 0, just return it
        if x0 >= 0:
            return (x0, y0)
        else:
            return None

    # Compute minimal t to make x >= 0
    from math import ceil

    t_min = ceil(-x0 / b_div)

    x = x0 + t_min * b_div
    y = y0 - t_min * a_div  # note sign change for y

    if x >= 0:
        return (x, y)
    else:
        return None


