def decode_list(seq):
    result = []
    i = 0
    n = len(seq)
    while i < n:
        if i + 1 < n and isinstance(seq[i], int):
            count = seq[i]
            value = seq[i + 1]
            result.extend([value] * count)
            i += 2
        else:
            result.append(seq[i])
            i += 1
    return result


