def get_total_number_of_sequences(N: int, K: int) -> int:
    # dp[i][x] = number of sequences of length i ending with x
    # Elements are in [1, N]
    # Each element >= 2 * previous element

    if K == 0:
        return 0
    if K == 1:
        return N

    dp_prev = [1] * (N + 1)  # for sequences of length 1, count=1 for each element
    # prefix sums for dp_prev
    prefix_sum = [0] * (N + 2)
    for i in range(1, N + 1):
        prefix_sum[i] = prefix_sum[i - 1] + dp_prev[i]

    for length in range(2, K + 1):
        dp_curr = [0] * (N + 1)
        for x in range(1, N + 1):
            # Previous element p must satisfy p <= x//2
            max_prev = x // 2
            if max_prev >= 1:
                dp_curr[x] = prefix_sum[max_prev]
            else:
                dp_curr[x] = 0
        dp_prev = dp_curr
        # update prefix sums
        prefix_sum[0] = 0
        for i in range(1, N + 1):
            prefix_sum[i] = prefix_sum[i - 1] + dp_prev[i]

    return sum(dp_prev[1:])


