def remove_column(collection, pos):
    result = []
    for inner in collection:
        if not (0 <= pos < len(inner)):
            # If pos is out of range for this inner iterable, leave it unchanged
            removed = inner
        else:
            removed = inner[:pos] + inner[pos+1:]
        # Preserve the type of the inner iterable
        if isinstance(inner, tuple):
            removed = tuple(removed)
        result.append(removed)
    # Preserve the outer iterable type
    if isinstance(collection, tuple):
        return tuple(result)
    return result


