def find_Max(nums):
    left, right = 0, len(nums) - 1
    while left < right:
        mid = (left + right) // 2
        if nums[mid] > nums[right]:
            left = mid + 1
        else:
            right = mid
    # left is now the index of the smallest value (rotation pivot)
    # The greatest value is just before the smallest value, or at the end if pivot is 0
    pivot = left
    if pivot == 0:
        return nums[-1]
    else:
        return nums[pivot - 1]


