from typing import List

def substract_elements(groups1: List[List[int]], groups2: List[List[int]]) -> List[List[int]]:
    """
    Subtract elements positionally between two sequences of groups.
    For each pair of inner lists at the same index, subtract elements of groups2 from groups1 element-wise.
    If groups2 is shorter, treat missing groups as empty lists.
    If inner lists differ in length, treat missing elements as zero.
    """
    result = []
    max_len = max(len(groups1), len(groups2))
    for i in range(max_len):
        g1 = groups1[i] if i < len(groups1) else []
        g2 = groups2[i] if i < len(groups2) else []
        max_inner_len = max(len(g1), len(g2))
        subtracted = []
        for j in range(max_inner_len):
            val1 = g1[j] if j < len(g1) else 0
            val2 = g2[j] if j < len(g2) else 0
            subtracted.append(val1 - val2)
        result.append(subtracted)
    return result


