def lucky_num(n):
    numbers = list(range(1, 2 * n * 10))  # overshoot to ensure enough lucky numbers
    idx = 1
    while len(numbers) < n or idx < len(numbers):
        step = numbers[idx]
        if step > len(numbers):
            break
        # Remove every step-th element (1-based index)
        numbers = [num for i, num in enumerate(numbers, start=1) if i % step != 0]
        idx += 1
    return numbers[:n]


