def compute_Last_Digit(a: int, b: int) -> int:
    if a > b:
        return 0
    if a == b:
        return 1
    result = 1
    for i in range(a + 1, b + 1):
        result = (result * (i % 10)) % 10
        # If result becomes 0, we can break early
        if result == 0:
            break
    return result


