def dif_Square(n: int) -> bool:
    # n = a^2 - b^2 = (a-b)(a+b)
    # Let x = a-b, y = a+b, so n = x*y
    # Since a, b integers => (x + y) and (y - x) must be even => x and y have same parity.
    # We need to check if n can be factored into two integers x, y of same parity such that x*y = n.

    # Special case: 0 = 0^2 - 0^2
    if n == 0:
        return True

    # Iterate over all divisors x of n (positive and negative) and check if y = n//x
    # has the same parity as x.
    abs_n = abs(n)
    for x in range(1, int(abs_n**0.5) + 1):
        if abs_n % x == 0:
            y = abs_n // x
            # Check positive divisors
            for (a, b) in [(x, y), (-x, -y)]:
                if a * b == n and (a % 2) == (b % 2):
                    return True
            # Check mixed sign divisors if n < 0
            if n < 0:
                for (a, b) in [(x, -y), (-x, y)]:
                    if a * b == n and (a % 2) == (b % 2):
                        return True
    return False


