def next_smallest_palindrome(num: int) -> int:
    def is_all_nines(s):
        return all(ch == '9' for ch in s)

    s = str(num + 1)  # strictly greater than num
    length = len(s)

    # If all digits are 9, e.g. 9, 99, 999, next palindrome is 10..01
    if is_all_nines(s):
        return int("1" + ("0" * (length - 1)) + "1")

    # Split s into left, middle, right
    mid = length // 2
    left = s[:mid]
    if length % 2 == 0:
        middle = ""
        right = s[mid:]
    else:
        middle = s[mid]
        right = s[mid+1:]

    # Form palindrome by mirroring left + middle
    if middle:
        palindrome = left + middle + left[::-1]
    else:
        palindrome = left + left[::-1]

    if int(palindrome) >= int(s):
        return int(palindrome)

    # Need to increment the middle part and propagate carry if needed
    if middle:
        # Increment middle digit and handle carry
        incremented = str(int(left + middle) + 1)
        if len(incremented) > len(left + middle):  # carry overflow (e.g. 999 +1 = 1000)
            left = incremented[:-1]
            middle = incremented[-1]
        else:
            left = incremented[:-1]
            middle = incremented[-1]
        palindrome = left + middle + left[::-1]
    else:
        # Even length, increment left part and mirror
        incremented = str(int(left) + 1)
        if len(incremented) > len(left):  # carry overflow
            left = incremented
        else:
            left = incremented
        palindrome = left + left[::-1]

    return int(palindrome)


