def find_Max(arr, low, high):
    if low == high:
        return arr[low]
    mid = (low + high) // 2
    # If mid element is greater than next element, mid is max
    if mid < high and arr[mid] > arr[mid + 1]:
        return arr[mid]
    # If mid element is smaller than previous element, previous is max
    if mid > low and arr[mid] < arr[mid - 1]:
        return arr[mid - 1]
    # Decide which half to explore
    if arr[low] >= arr[mid]:
        return find_Max(arr, low, mid - 1)
    else:
        return find_Max(arr, mid + 1, high)


