def filter_data(students, min_height=None, max_height=None, min_width=None, max_width=None):
    """
    Filters the input dictionary of students by height and width bounds.

    Parameters:
        students (dict): A dict keyed by student ID, each value a dict with keys 'height' and 'width'.
        min_height (float or None): Minimum height to include (inclusive).
        max_height (float or None): Maximum height to include (inclusive).
        min_width (float or None): Minimum width to include (inclusive).
        max_width (float or None): Maximum width to include (inclusive).

    Returns:
        dict: Filtered dictionary containing only students whose height and width are within the specified bounds.
    """
    def in_bounds(value, min_val, max_val):
        if min_val is not None and value < min_val:
            return False
        if max_val is not None and value > max_val:
            return False
        return True

    return {
        sid: info
        for sid, info in students.items()
        if 'height' in info and 'width' in info
        and in_bounds(info['height'], min_height, max_height)
        and in_bounds(info['width'], min_width, max_width)
    }


