def lucky_num(n):
    # Start with a list of odd numbers starting from 1 (1,3,5,7,...)
    # We'll generate a list long enough to find n lucky numbers
    # Since lucky numbers are sparser than odds, start with a generous size
    limit = 2 * n * n  # heuristic upper bound
    numbers = list(range(1, limit, 2))

    idx = 1  # start from the second element (index 1) for the sieve steps

    while idx < len(numbers):
        step = numbers[idx]
        if step > len(numbers):
            break
        # Remove every step-th number from the list, counting from 1-based index
        # The counting starts at position step-1 (0-based), then remove every step-th element
        # But the sieve is applied repeatedly with updated list each time
        del numbers[step-1::step]
        idx += 1
        if len(numbers) >= n and idx >= n:
            # If we have at least n numbers and index passed n, no need to continue
            break

    return numbers[:n]


