def get_noOfways(n, m):
    # m is fixed at 2, so we ignore it in calculations
    # Number of ways to tile 2 x n board with 2 x 1 tiles is Fibonacci-like:
    # ways(n) = ways(n-1) + ways(n-2), with ways(0)=1, ways(1)=1

    if n < 0:
        return 0
    if n == 0 or n == 1:
        return 1

    prev, curr = 1, 1
    for _ in range(2, n + 1):
        prev, curr = curr, prev + curr
    return curr


