import re
from typing import List

def parse_nested_parens(paren_string: str) -> List[int]:
    groups = re.findall(r'\(+\)+|\(+[^\(\)]*\)+|[()]+', paren_string)
    # Actually, above pattern is complex and not fully correct for splitting by non-paren chars.
    # Instead, better to split by any sequence of non-parentheses characters:
    groups = re.split(r'[^()]+', paren_string)
    # Filter out empty strings:
    groups = [g for g in groups if g]

    results = []
    for group in groups:
        max_depth = 0
        current_depth = 0
        for ch in group:
            if ch == '(':
                current_depth += 1
                if current_depth > max_depth:
                    max_depth = current_depth
            elif ch == ')':
                current_depth -= 1
        results.append(max_depth)
    return results


