def circular_shift(x, shift):
    s = str(x)
    n = len(s)
    if abs(shift) > n:
        return s[::-1]
    shift %= n
    if shift == 0:
        return s
    if shift > 0:
        # left shift by shift
        return s[shift:] + s[:shift]
    else:
        # shift < 0, right shift by abs(shift)
        shift = -shift
        return s[-shift:] + s[:-shift]


