def anti_shuffle(s):
    result = []
    i = 0
    n = len(s)
    while i < n:
        if s[i] == ' ':
            result.append(' ')
            i += 1
        else:
            start = i
            # Move i until next space or end of string
            while i < n and s[i] != ' ':
                i += 1
            token = s[start:i]
            # Sort characters of token in ascending ascii order
            sorted_token = ''.join(sorted(token))
            result.append(sorted_token)
    return ''.join(result)


