def parse_nested_parens(paren_string: str) -> List[int]:
    # For each group, accumulate +1 for '(' and -1 for ')' and find the max depth.
    return list(
        map(
            lambda group: max(itertools.accumulate(map(lambda c: 1 if c == '(' else -1, group)), default=0),
            paren_string.split()
        )
    )


