from typing import List, Tuple
from collections import Counter

def parse_music(music_string: str) -> Tuple[List[int], str]:
    notes = music_string.split()
    beat_map = {'o': 4, 'o|': 2, '.|': 1}
    beats = list(map(beat_map.get, notes))
    counts = Counter(notes)
    max_count = max(counts.values())
    candidates = [note for note, count in counts.items() if count == max_count]
    # In case of tie, return the note with the longest beat
    most_common_note = max(candidates, key=lambda n: beat_map[n])
    return beats, most_common_note


