from typing import List, Any, Tuple

def filter_integers(values: List[Any], format: str) -> Tuple[List[int], str]:
    """ 
    Filter given list of any Python values only for integers and return them as a list
    while maintaining the order of non-integer elements in the original list as a space-joined string.
    The output integers should be returned as a list of ints regardless of 'format' parameter,
    and non-integers as space-joined string.
    Note: 
    - Avoid using loops, sort or filter functions in your code.
    - The function should also work when the input is a string.
    """
    # Convert string input to list of chars
    if isinstance(values, str):
        values = list(values)

    # Recursive extraction of integers
    def extract_ints(lst):
        if not lst:
            return []
        head, *tail = lst
        return ([head] if isinstance(head, int) else []) + extract_ints(tail)

    # Recursive extraction of non-integers (converted to string)
    def extract_non_ints(lst):
        if not lst:
            return []
        head, *tail = lst
        rest = extract_non_ints(tail)
        if not isinstance(head, int):
            return [str(head)] + rest
        else:
            return rest

    ints = extract_ints(values)
    non_ints_str = " ".join(extract_non_ints(values))

    return (ints, non_ints_str)


