def monotonic(l):
    if isinstance(l, list):
        # For lists: duplicates allowed, return only boolean
        # Check non-decreasing (l[i] <= l[i+1]) or non-increasing (l[i] >= l[i+1])
        # Return (True, sum) if monotonic, else (False, sum)
        # No loops or sorting; use recursion

        def non_decreasing(i=0):
            if i == len(l) - 1:
                return True
            return l[i] <= l[i + 1] and non_decreasing(i + 1)

        def non_increasing(i=0):
            if i == len(l) - 1:
                return True
            return l[i] >= l[i + 1] and non_increasing(i + 1)

        if len(l) == 0:
            return True, 0  # empty list considered monotonic, sum 0

        monotonic_bool = non_decreasing() or non_increasing()
        return monotonic_bool, sum(l)

    elif isinstance(l, str):
        # For strings: duplicates cause False (just False, no tuple)
        # Check strictly increasing (l[i] < l[i+1]) or strictly decreasing (l[i] > l[i+1])
        # Return True, l if monotonic; else False

        if len(set(l)) != len(l):
            return False

        def strictly_increasing(i=0):
            if i == len(l) - 1:
                return True
            return l[i] < l[i + 1] and strictly_increasing(i + 1)

        def strictly_decreasing(i=0):
            if i == len(l) - 1:
                return True
            return l[i] > l[i + 1] and strictly_decreasing(i + 1)

        if len(l) == 0:
            return True, ""

        if strictly_increasing() or strictly_decreasing():
            return True, l
        else:
            return False


