from collections import Counter
from typing import List, Union

def search(lst: List[Union[int, str]]) -> Union[int, str]:
    freq = Counter(lst)
    # Find all positive integers satisfying freq[x] >= x
    candidates = [x for x in freq if isinstance(x, int) and x > 0 and freq[x] >= x]
    if candidates:
        return max(candidates)
    # If no such integer found, and list has strings, return the greatest string
    strings = [x for x in freq if isinstance(x, str)]
    if strings:
        return max(strings)
    return -1


