def move_one_ball(arr):
    if not arr:
        return True

    n = len(arr)

    def is_sorted(a):
        return all(a[i] <= a[i + 1] for i in range(len(a) - 1))

    # If already sorted non-empty, return True
    if is_sorted(arr):
        return True

    # Since elements are unique, find the index where the order breaks
    # The break point is where arr[i] > arr[i+1]
    # There must be at most one such break for the array to be a rotation of a sorted array
    breaks = [i for i in range(n - 1) if arr[i] > arr[i + 1]]
    if len(breaks) != 1:
        return False

    break_idx = breaks[0]

    # Number of right shifts needed to make array sorted is n - (break_idx + 1)
    shifts = n - (break_idx + 1)

    # Verify by rotating right shifts times and check if sorted
    rotated = arr[-shifts:] + arr[:-shifts]
    if is_sorted(rotated):
        return shifts
    else:
        return False


