def select_words(s, n):
    if not s:
        return []
    vowels = set("aeiouAEIOU")
    words = s.split()
    def consonant_count(word):
        return sum(c.isalpha() and c not in vowels for c in word)
    filtered = list(filter(lambda w: consonant_count(w) == n, words))
    # stable sort by alphabetical order but maintain original order for ties
    # Since we must maintain original order and sort alphabetically,
    # we interpret it as sorting by word alphabetically but preserving relative order for duplicates.
    # Python's sort is stable, so sorting once by word alphabetically preserves relative order for words equal alphabetically.
    # However, sorting just once will reorder the words completely.
    # The instruction is contradictory:
    # "The function must sort the output list in alphabetical order,
    # but also you must maintain the original order of words."
    # These contradict unless words are all unique or sorting is done partially.
    # According to the user's authoritative answer, we must preserve original order,
    # so we will not reorder.
    # The user said "return a list of matching words themselves, preserving their original order".
    # So we do NOT sort.
    # So the sorting instruction is overridden by the user's clarification.
    return filtered


