def maximum(arr, k):
    def insertion_sort(nums):
        for i in range(1, len(nums)):
            key = nums[i]
            j = i - 1
            while j >= 0 and nums[j] > key:
                nums[j + 1] = nums[j]
                j -= 1
            nums[j + 1] = key
        return nums

    if k == 0:
        return []

    # Find the k largest elements without using built-in sort
    # We'll select k times the max element and remove it from a copy to avoid duplicates
    arr_copy = arr[:]
    max_k = []
    for _ in range(k):
        max_val = arr_copy[0]
        max_idx = 0
        for i in range(1, len(arr_copy)):
            if arr_copy[i] > max_val:
                max_val = arr_copy[i]
                max_idx = i
        max_k.append(max_val)
        arr_copy.pop(max_idx)

    # Sort max_k in ascending order using insertion sort
    return insertion_sort(max_k)


