def digits(n):
    s = str(n)
    odds = [int(d) for d in s if int(d) % 2 == 1]
    evens = [int(d) for d in s if int(d) % 2 == 0]

    if not odds:
        # all digits even -> return 0 (int)
        return 0
    if not evens:
        # all digits odd -> return product of odds (int)
        prod_odd = 1
        for o in odds:
            prod_odd *= o
        return prod_odd

    # mixed digits -> return product of odd digits (int)
    prod_odd = 1
    for o in odds:
        prod_odd *= o
    return prod_odd


