def move_one_ball(arr):
    if not arr:
        return True
    n = len(arr)
    # Since elements are unique, sorted array is strictly increasing
    # Check if arr is a rotation of the sorted array
    sorted_arr = sorted(arr)
    # We can find the rotation point by comparing arr to sorted_arr
    # The rotation point is the index in arr where sorted_arr[0] occurs
    try:
        start = arr.index(sorted_arr[0])
    except ValueError:
        return False  # should not happen since sorted_arr[0] is in arr

    # Check if rotating arr by start to the left matches sorted_arr
    # Rotating to the left by start is equivalent to right shift by n - start
    # So, check if arr[start:] + arr[:start] == sorted_arr
    rotated = arr[start:] + arr[:start]
    return rotated == sorted_arr


