import re

def anti_shuffle(t):
    # Split input into words and spaces, preserving all spaces exactly
    parts = re.findall(r'\S+|\s+', t)
    result_parts = []
    for part in parts:
        if part.isspace():
            # preserve spaces exactly
            result_parts.append(part)
        else:
            # sort characters of the word ascending by their Unicode code points
            sorted_part = ''.join(sorted(part))
            result_parts.append(sorted_part)
    return ''.join(result_parts)


