def move_one_ball(seq):
    if not seq:
        return True

    n = len(seq)
    sorted_seq = sorted(seq)

    # Since values are distinct, we can find the rotation point by looking for the index of the smallest element.
    # The sequence can be obtained by rotating sorted_seq by some amount.
    # Check if seq is a rotation of sorted_seq.

    # Find index of smallest element in seq
    min_val = min(seq)
    min_index = seq.index(min_val)

    # Rotate seq to start from min_index and check if it equals sorted_seq
    rotated = seq[min_index:] + seq[:min_index]
    return rotated == sorted_seq


