def select_words(text, count):
    vowels = set("aeiouAEIOU")
    if not text:
        return []
    words = text.split()
    result = []
    for w in words:
        consonant_count = sum(1 for c in w if c.isalpha() and c not in vowels)
        if consonant_count == count:
            result.append(w)
    return result


