def order_by_points(items):
    def score(n):
        s = str(abs(n))
        digits = list(map(int, s))
        total = sum(digits)
        if n < 0 and digits:
            total -= 2 * digits[0]
        return total
    return sorted(items, key=lambda x: score(x))


