def circular_shift(x, shift):
    """Circular shift the digits of the integer x, shift the digits
    and return the result as a string.
    Positive shift rotates right, negative shift rotates left.
    """
    s = str(abs(x))
    n = len(s)
    if n == 0:
        return str(x)
    shift = shift % n
    if shift == 0:
        shifted = s
