def move_one_ball(arr):
    if not arr:
        return True
    sorted_arr = sorted(arr)
    n = len(arr)
    # Try all possible right shifts on sorted_arr to see if any matches arr
    for shift in range(n):
        # Right shift by 'shift': last 'shift' elements move to front
        shifted = sorted_arr[-shift:] + sorted_arr[:-shift]
        if shifted == arr:
            return True
    return False


