def fizz_buzz(n: int):
    """Return the number of times the digit 7 appears in integers less than n which are divisible by 11 or 13,
    excluding 0 and counting each number only once.
    """
    count = 0
    seen = set()
    for x in range(1, n):
        if x % 11 == 0 or x % 13 == 0:
            if x not in seen:
                count += str(x).count('7')
                seen.add(x)
    return count


