def move_one_ball(arr):
    if not arr:
        return True

    n = len(arr)
    # Since all elements are unique, a sorted array has strictly increasing order.
    sorted_arr = sorted(arr)

    # Try all possible right shifts and check if any produces the sorted array
    # Right shift by k means:
    # arr after right shift by k == arr[-k:] + arr[:-k]
    for k in range(n):
        shifted = arr[-k:] + arr[:-k]
        if shifted == sorted_arr:
            return True
    return False


