def order_by_points(nums):
    def digit_sum(n):
        s = str(n)
        if s[0] == '-':
            # first digit after minus is negative
            first_digit = -int(s[1])
            rest_digits = s[2:]
            rest_sum = sum(int(ch) for ch in rest_digits)
            return first_digit + rest_sum
        else:
            return sum(int(ch) for ch in s)
    return sorted(enumerate(nums), key=lambda x: digit_sum(x[1]) + 1e-9*x[0])
    # using enumerate to keep original order on ties
    # tiny addition to key to ensure stable order by index
    # but stable sort would do anyway
    # but we must use original index for tie breaking, so key is (digit_sum, original_index)
def order_by_points(nums):
    def digit_sum(n):
        s = str(n)
        if s[0] == '-':
            first_digit = -int(s[1])
            rest_sum = sum(int(ch) for ch in s[2:])
            return first_digit + rest_sum
        else:
            return sum(int(ch) for ch in s)
    return [x[1] for x in sorted(enumerate(nums), key=lambda x: (digit_sum(x[1]), x[0]))]


