from typing import List

def parse_nested_parens(paren_string: str) -> List[int]:
    result = []
    current_depth = 0
    max_depth = 0
    in_group = False

    for ch in paren_string:
        if ch == '(':
            current_depth += 1
            in_group = True
            if current_depth > max_depth:
                max_depth = current_depth
        elif ch == ')':
            current_depth -= 1
        else:
            # Non-parenthesis character signals end of group (if any)
            if in_group:
                result.append(max_depth)
                max_depth = 0
                current_depth = 0
                in_group = False

    # If string ends in a group, append its max_depth
    if in_group:
        result.append(max_depth)

    return result


