def circular_shift(x, shift):
    s = str(abs(x))
    n = len(s)
    if n == 0:
        return ""
    shift = shift % n
    # Positive shift rotates digits to the right, negative to the left
    if shift == 0:
        return s
    elif shift > 0:
        return s[-shift:] + s[:-shift]
    else:
        shift = -shift
        return s[shift:] + s[:shift]


