import re

def anti_shuffle(s):
    # Split the string into words and spaces, preserving all spaces exactly
    parts = re.split(r'(\s+)', s)
    result = []
    for part in parts:
        # If this part is all spaces, keep as is
        if part.isspace() or part == '':
            result.append(part)
        else:
            # Sort characters of the word by ASCII
            sorted_word = ''.join(sorted(part))
            result.append(sorted_word)
    return ''.join(result)


