def move_one_ball(arr):
    if not arr:
        return True

    n = len(arr)
    # Check if arr is already sorted
    if all(arr[i] <= arr[i+1] for i in range(n-1)):
        return True

    # Try all possible right shifts
    for shift in range(1, n):
        # right shift by `shift` positions means:
        # new array = arr[-shift:] + arr[:-shift]
        shifted = arr[-shift:] + arr[:-shift]
        if all(shifted[i] <= shifted[i+1] for i in range(n-1)):
            return True

    return False


