import re

def select_words(s: str, n: int) -> list[str]:
    vowels = set("aeiouAEIOU")
    words = re.findall(r'\b\w+\b', s)
    result = []
    for w in words:
        consonant_count = sum(1 for ch in w if ch.isalpha() and ch not in vowels)
        if consonant_count == n:
            result.append(w)
    return result


