def parse_music(music: str) -> list[int]:
    """
    Parses a piece of music given as a string of notes with optional accidentals and octave numbers,
    and returns the corresponding list of MIDI note numbers.

    This implementation assumes standard Western note naming:
    - Notes: C, D, E, F, G, A, B
    - Accidentals: # (sharp), b (flat)
    - Octave number: integer (e.g. 4)

    Each note is separated by whitespace.
    Example: "C4 D#4 A3" -> [60, 63, 57]

    If a note is invalid, it is ignored.
    """
    note_base = {'C': 0, 'D': 2, 'E': 4, 'F': 5, 'G': 7, 'A': 9, 'B': 11}

    result = []
    for token in music.split():
        if len(token) < 2:
            continue  # too short to be valid note + octave

        # Parse note letter
        note_char = token[0].upper()
        if note_char not in note_base:
            continue

        # Parse accidental (if present)
        accidental = 0
        pos = 1
        if len(token) > 2 and token[1] in ('#', 'b'):
            accidental = 1 if token[1] == '#' else -1
            pos = 2

        # Parse octave number (must be after note and accidental)
        octave_str = token[pos:]
        if not octave_str.isdigit():
            continue
        octave = int(octave_str)

        midi_number = 12 * (octave + 1) + note_base[note_char] + accidental
        if 0 <= midi_number <= 127:
            result.append(midi_number)

    return result


