def will_it_fly(q, w):
    if isinstance(q, dict):
        ok = q.get('ok', False)
        weight = q.get('weight', float('inf'))
        return bool(ok) and weight <= w
    else:
        # Assume q is a sequence of numeric elements representing weights
        total_weight = sum(q)
        # Condition "ok" defaults to True if q is a sequence (no explicit 'ok')
        return total_weight <= w


