import re

def anti_shuffle(data: str) -> str:
    # Split data into words and blanks (spaces)
    parts = re.split(r'(\s+)', data)
    # For each word (non-blank), sort the letters; keep blanks as is
    for i in range(0, len(parts), 2):
        parts[i] = ''.join(sorted(parts[i]))
    return ''.join(parts)


