def anti_shuffle(s):
    result = []
    i = 0
    n = len(s)
    while i < n:
        if s[i] == ' ':
            result.append(' ')
            i += 1
        else:
            j = i
            while j < n and s[j] != ' ':
                j += 1
            token = s[i:j]
            sorted_token = ''.join(sorted(token))
            result.append(sorted_token)
            i = j
    return ''.join(result)


