import re

def anti_shuffle(s):
    def reorder_word(word):
        # Separate trailing punctuation (non-alphanumeric) from the word
        m = re.match(r"([A-Za-z0-9]+)([^A-Za-z0-9]*)$", word)
        if not m:
            # Word might be only punctuation or empty, just return as is
            return word
        core, punct = m.groups()
        # Sort characters in core in ascending ASCII order
        sorted_core = ''.join(sorted(core))
        return sorted_core + punct

    # Split the string by spaces, keeping spaces to preserve exact spacing
    tokens = re.split(r'(\s+)', s)
    # Process only the words (non-space tokens)
    for i, token in enumerate(tokens):
        if not token.isspace():
            tokens[i] = reorder_word(token)
    return ''.join(tokens)


